window.MONSTER_CHUNK_140 = [{"name":"Rawbones","cr":8,"xp":4800,"alignment":"NE","size":"Medium","type":"undead","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["nauseating aura (20 ft., DC 19)"],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +6 natural","hp":91,"hd":"14d8+28","hdvalue":14,"fort":8,"ref":8,"will":10,"defensive_abilities":["channel resistance +2"],"dr":"10/magic or silver","immunities":["cold","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +15 (1d8+4) or entrails lash +14 (1d4+4 plus  grab)","space":"5 ft.","reach":"5 ft. (10 ft. with entrails lash)","special_attacks":[{"type":"strangulation"},{"type":"vomit gore"}],"strength":19,"dexterity":14,"intelligence":12,"wisdom":12,"charisma":14,"baseatk":10,"cmb":14,"cmb_special":"+4 vs. grapple","cmd":26,"feats":[{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (slam)"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Acrobatics","value":13},{"skill":"Climb","value":18},{"skill":"Escape Artist","value":14},{"skill":"Intimidate","value":17},{"skill":"Perception","value":16},{"skill":"Stealth","value":17}],"languages":["Common","Infernal"],"environments":["any land"],"organizations":["solitary","gang (2-4)"],"treasure":"standard","description_visual":"Skulking towards you is what appears to be a freshly skinned and cleaned corpse. It is a bloody, skeletal creature with bits of flesh and muscle still clinging to its wet bones. Its entrails and organs hang loosely in its torso, sometimes even dropping out entirely. Its eyes roll about in its eye sockets as it seeks its prey.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Nauseating Aura","kind":"Su","details":"A rawbones emanates a sickening aura that reeks of death in a 20-foot radius. Any creature that comes within that area must succeed on DC 19 Fortitude save or become nauseated for as long as they remain within the area a 1 minute after leaving the area. A creature that makes a successful save is immune to the nauseating aura of that rawbones for one day. The save DC is Charisma-based."},{"type":"Strangulation","kind":"Ex","details":"When a rawbones hits an opponent of up to one size larger with its entrails lash, it can then attempt to start a grapple as a free action without provoking attacks of opportunity. If it succeeds on its grapple check, it establishes a hold and deals 1d4 points of strangulation damage per round in addition to normal damage to the grappled opponent each round that the hold is maintained."},{"type":"Vomit Gore","kind":"Su","details":"Three times per day, a rawbones can spit a blast of blood and gore in a 20-foot cone that deals 7d6 points of damage (DC 19 Reflex save for half). The save DC is Charisma-based."}],"description":"A rawbones is an undead creature that comes into being when a tortured person rises from the grave. Rawbones are commonly found in ancient dungeons that hold old torture chambers and prison cells. Some are also found haunting the local cemeteries where a tortured person was laid to rest. While disgusting in appearance, there is something in the magic (or evil) of a rawbones that keeps it looking ‘fresher' that most of its other undead kin.\n\nLike many undead, rawbones despise the living and seek to harm such creatures whenever they can. A rawbones is generally a solitary creature though it is possible more than one could be encountered together (e.g., an ancient dungeon where a mass torture/execution took place or a mass grave where tortured and broken bodies where laid to rest).\n\nA rawbones stands 6 to 6-1/2 ft. tall and weighs roughly 140 pounds.\n\nIts bones are stained red with fresh blood which seems to continually weep from the creature's body. Bits of flesh and muscle fall away from it as it moves about and its entrails often drag the ground behind it or are wrapped around the creature's forearms.\n\nA rawbones speaks Common and at least one other language.\n\nA rawbones attacks primarily with its powerful fists, but it has other weapons at its disposal. It can vomit forth a horrifying spray of blood and gore or use its entrails as a ranged weapon which it loops around an opponent's neck in an attempt to strangle it. While battling its foes, it attempts to keep them within range of its nauseating aura.\n\nA rawbones' natural weapons are treated as magic weapons for the purpose of overcoming damage reduction.","ecology":"","habitat_society":""},{"name":"Riptide Horror","cr":8,"xp":4800,"alignment":"LE","size":"Medium","type":"magical beast","subtypes":["aquatic"],"init":6,"senses":[{"type":"blindsight","modifier":"30 ft."}],"ac":20,"ac_touch":12,"ac_flat_footed":18,"ac_mods":"+2 Dex, +8 natural","hp":63,"hd":"6d10+30","hdvalue":6,"fort":10,"ref":7,"will":4,"dr":"10/piercing or slashing","weaknesses":["vulnerability to electricity"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":40}],"melee":"6 tentacles +5 (1d4+1 plus grab plus poison) and 6  bites +4 (1d6+1)","space":"5 ft.","reach":"5 ft. (10 ft. with tentacle)","special_attacks":[{"type":"paralytic poison"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"spider climb"}]}],"strength":17,"dexterity":15,"constitution":20,"intelligence":8,"wisdom":9,"charisma":8,"baseatk":6,"cmb":7,"cmd":19,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Perception","value":4},{"skill":"Stealth","value":7,"special":"+17 in murky water"},{"skill":"Swim","value":16}],"sq":[{"type":"amphibious"}],"environments":["temperate marshes"],"organizations":["solitary","pair","colony (2-8)"],"treasure":"none","description_visual":"This vile, grayish-tan tubeworm is longer than a man. It has six eyeless heads and each mouth is lined with inward curving, serrated teeth. Six long grayish-tan tentacles protrude from the middle of its body.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Tentacle-contact; save Fort DC 18; frequency 1/round for 1d4 rounds; effect 1d4 Dex plus paralysis Fort DC 18 1d4 rounds, cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"The terrifying riptide horror is a giant, sightless tubeworm found in sea caves or deep within desolate marshes. They are carnivorous creatures and have a voracious appetite that is only sated with meat, preferably that of warm-blooded humanoids or reptiles.\n\nOpportunistic, ambush hunters, riptide horrors wait for prey to come to them. They can go several weeks without eating, and sometimes do, but if a meal is readily available, the horror doesn't hesitate to kill and devour it. Such a meal is placed in a \"reserve\" stomach-like sac. When the food supply is low, the riptide horror delves into its reserve and draws sustenance from the stored food.\n\nRiptide horrors mate once a year, usually in flooded sea caves. The female crawls into the male's lair and deposits a sticky, greenish-tan mass of eggs on the wall of the cave. The male fertilizes the eggs and in 4 months, the eggs begin to hatch. Juveniles are excellent swimmers and leave the cave as soon as they hatch. As a riptide horror ages, its body secretes a substance that forms a shell-like carapace on its dorsal side.\n\nRiptide horrors prefer to attack from ambush; sitting unmoving until potential prey moves within range. Often, they use their spider climb ability to cling to sea cave walls where their unsuspecting prey walks underneath them. Once prey wanders too close, the riptide horror lashes out with its tentacles and attempts to grab its meal. Grabbed foes are subjected to its paralytic poison and are bitten by its razor-sharp teeth.","ecology":"","habitat_society":""},{"name":"Salt Drake","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"dragon","subtypes":["earth"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+1 Dex, +8 natural, -1 size","hp":104,"hd":"11d12+33","hdvalue":11,"hp_mods":["fast healing 2"],"fort":10,"ref":8,"will":8,"immunities":["paralysis","sleep"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":150,"maneuverability":"poor"}],"melee":"bite +13 (2d6+4), 2 claws +13 (1d8+3), 2 wings +11 (1d6+1), tail slap +11 (1d8+4)","space":"10 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"30 ft. cone, DC 18, 3d6 slashing plus 1 Con damage"}],"strength":17,"dexterity":13,"constitution":16,"intelligence":4,"wisdom":13,"charisma":11,"baseatk":11,"cmb":15,"cmd":26,"cmd_special":"+4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Hover"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":9},{"skill":"Perception","value":21},{"skill":"Stealth","value":11}],"languages":["Draconic"],"environments":["temperate plains","warm plains"],"organizations":["solitary","pair","clutch (2-5)"],"treasure":"none","description_visual":"This powerful creature resembles a blue dragon with mottled black wings and crimson eyes. Its ears are frilled and swept back against its head.","group":"Drake","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A salt drake's breath weapon is a 30 ft. cone of razor-sharp salt crystals. In addition to dealing slashing damage the salt crystals absorb bodily fluids, dealing 1 point of Constitution damage to living targets."}],"description":"Salt drakes are found in warm, arid climates such as deserts or salt flats. Salt drakes are omnivorous creatures and very territorial, even fighting among themselves to protect their domains. Most encounters are with a solitary drake. Only in the midsummer months is it common to find a mated pair or family. A salt drake's scales range from dull blue to midnight blue, and it is often mistaken for a young blue dragon. Salt drakes range from 8 ft. to 30 ft. long. Though difficult to train, salt drakes are favored as mounts by goblins, gnolls, and hobgoblins. A salt drake's primary diet consists of large quantities of salt. This diet enables the drake to spew salt at its opponents. A salt drake opens combat from the air using its salt spray breath weapon. If unable to utilize its breath weapon, it relies on its claws and bite to finish off any remaining opponents. Training a Salt Drake A salt drake requires training before it can bear a rider in combat. To be trained, a salt drake must have a friendly attitude toward the trainer (this can be achieved through a successful Diplomacy check). Training a friendly salt drake requires ten weeks of work and a DC 30 Handle Animal check. Riding a salt drake requires an exotic saddle. A salt drake can fight while carrying a rider, but the rider cannot also attack unless he or she succeeds on a Ride check. Salt drake eggs are worth 6,000 gp apiece on the open market, while young are worth 12,000 gp each. Professional trainers charge 2,000 gp to rear or train a dragonnel. Carrying Capacity: A light load for a salt drake is up to 516 pounds; a medium load, 517-1,038 pounds, and a heavy load, 1,039-1,560 pounds.","ecology":"","habitat_society":""},{"name":"Sand Kraken","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"magical beast","init":4,"senses":[{"type":"tremorsense","modifier":"60 ft."}],"ac":21,"ac_touch":9,"ac_flat_footed":21,"ac_mods":"+0 Dex, +12 natural, -1 size","hp":100,"hd":"8d10+60","hdvalue":8,"fort":12,"ref":6,"will":4,"speed":[{"type":"land","speed":10}],"melee":"10 tentacles +13 (1d4+5 plus grab) or bite +8 (2d6+2)","space":"10 ft.","reach":"10 ft. (20 ft. with tentacle)","special_attacks":[{"type":"constrict","details":"1d6+5"}],"strength":20,"dexterity":11,"constitution":23,"intelligence":2,"wisdom":10,"charisma":1,"baseatk":8,"cmb":14,"cmd":24,"cmd_special":"can't be tripped","feats":[{"feat":"Improve Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Perception","value":11}],"sq":[{"type":"camouflage"}],"environments":["warm deserts"],"organizations":["solitary"],"treasure":"none","description_visual":"A huge, bloated, eyeless, formless octopus rises from the sand. From its pale, yellow shapeless body sprouts ten long tentacles tipped with cruel barbed pads.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Camouflage","kind":"Ex","details":"Because it remains buried until it attacks, it takes a successful DC 20 Perception check to detect the presence of a sand kraken before it attacks. Anyone with ranks in Survival or Knowledge (nature) can use one of those skills instead of Perception to notice the sand kraken."},{"type":"Tentacles","kind":"Ex","details":"The only part of a sand kraken that is normally exposed is its tentacles. For combat purposes, the creature's tentacles are treated as separate weapons. A single tentacle has an AC 20 (touch 14) and 15 hit points. Once a tentacle takes more than 15 hit points of damage, it is destroyed. A sand kraken can no longer use the destroyed tentacle to make attacks, however the loss of a tentacle cause the creature no other penalties. Furthermore, damage dealt to a tentacle doesn't count against the creature's total hit points. Lost tentacles regrow in 1d4 days."}],"description":"The sand krakens are dangerous creatures encountered only in remote wastelands. A sand kraken keeps its body well concealed, buried deep in sand or loose rock, and inaccessible to most attacks. The creature never moves from the place where it digs its first burrow and once it settles in, will never again see the light of day. The only parts of a sand kraken that are usually seen are its tentacles, and by then it is often too late.\n\nSand krakens are omnivores, but prefer meat to any other food. Once it captures and kills its prey, it pulls the carcass down into its sandy lair, and devours it with its great central maw. For this reason, a number of scholars speculate a biological relationship between sand krakens and dustdiggers.\n\nFor most of its life, a sand kraken remains dormant and silent, buried several ft. below the surface of the ground. When it senses prey its tentacles swiftly rise to the surface. A sand kraken uses its initial attacks to immobilize its prey by constriction. Each tentacle has its own secondary brain, and can attack independently. While tentacles can be harmed and severed, the only true way to kill a sand kraken is to dig it up and destroy its body.","ecology":"","habitat_society":""},{"name":"Sepulchral Guardian","cr":8,"xp":4800,"alignment":"N","size":"Medium","type":"construct","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":21,"ac_touch":10,"ac_flat_footed":21,"ac_mods":"+11 natural","hp":75,"hd":"10d10+20","hdvalue":10,"fort":3,"ref":3,"will":3,"dr":"10/adamantine","immunities":["cold","construct traits","fire"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10}],"sr":19,"speed":[{"type":"land","speed":30}],"melee":"+1 longsword +18 (1d8+8), 2 slams +17 (2d6+7 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"dread"}],"strength":24,"dexterity":10,"wisdom":11,"charisma":12,"baseatk":10,"cmb":17,"cmd":27,"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"A humanoid wearing iron armor stands before you. In its hand it holds a wickedly sharp longsword. Its eyes show no signs of life.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Disease","kind":"Su","details":"Crypt Death: Disease-slam; save Fort DC 17; onset 1minute; frequency 1/day; effect 1d6 Con and 1d6 Str damage; cure 3 consecutive saves. A creature damaged by a sepulchral guardian's slam attack must succeed on a DC 17 Fortitude save or contract crypt death, a supernatural disease created long ago by a spellcaster whose name has been lost over time. The save DC is Constitution-based and includes a +2 racial bonus."},{"type":"Dread","kind":"Su","details":"Creatures viewing a sepulchral guardian must succeed on a DC 16 Will save or become shaken as long as the sepulchral guardian is \"alive\" and within 100 ft. and for 2d4 rounds afterwards. A successful save renders the target immune to the guardian's dread for 24 hours. The save DC is Charisma-based."}],"description":"Sepulchral guardians are specially constructed guardians created from the preserved corpses of dead humanoids that have been encased in iron.\n\nThey are created for one purpose and one purpose only: to guard the final resting place of a now dead creature. Once activated, a sepulchral guardian performs its task until it is destroyed. Even the death of its creator doesn't disrupt a sepulchral guardian as many are created to guard the final resting place of the one that created them.\n\nA sepulchral guardian appears as a humanoid standing just over 6 ft. tall. Its entire body, save its face is encased in a suit of iron. Its face, while humanoid, shows no signs of life, and its eyes are filled with the emptiness of an automaton. Most sepulchral guardians wield longswords, battleaxes, or other such weapons. A sepulchral guardian weighs about 900 pounds.\n\nSepulchral guardians cannot speak and don't utter any sound.\n\nSepulchral guardians attack with deadly accuracy, relying on either a longsword or their powerful fists in battle. They are relentless combatants and attack until destroyed or until their foes are slain or driven from the area they are protecting. A sepulchral guardian never gives pursuit, refusing to leave its assigned area.\n\nConstruction A sepulchral guardian' body is constructed from 500 pounds of iron mixed with rare chemicals totaling 1,000 gp and the preserved corpse of a single humanoid (which is encased in the iron).\n\nSEPULCHRAL GUARDIAN CL 11th; Price 41,000 gp Requirements Craft Construct, contagion, geas/quest, limited wish, polymorph any object, creator must be caster level 11th; Skill Craft (armor or weapons) DC 15; Cost 21,000 gp","ecology":"","habitat_society":"","gear":"+1 longsword"},{"name":"Seraph Genie","cr":8,"xp":4800,"alignment":"NG","size":"Large","type":"outsider","subtypes":["extraplanar","fire"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+4 Dex, +1 dodge, +6 natural, -1 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":7,"ref":11,"will":9,"immunities":["fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"mwk scimitar +14 (1d8+4 plus 1d6 fire) or 2 slams +13 (1d8+4 plus 1d6 fire)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"fire burst"},{"type":"heat"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"flame blade"},{"spell":"plane shift","details":"willing targets to elemental planes, Astral Plane, or Material Plane only"},{"spell":"produce flame"},{"spell":"pyrotechnics"}]},{"frequency":"1/day","spells":[{"spell":"fire storm"},{"spell":"wish","details":"to non-genies only"}]},{"frequency":"3/day","spells":[{"spell":"fireball"},{"spell":"flame strike"},{"spell":"invisibility","details":"self only"},{"spell":"see invisibility"},{"spell":"wall of fire"}]}],"strength":19,"dexterity":18,"constitution":18,"intelligence":14,"wisdom":15,"charisma":17,"baseatk":10,"cmb":15,"cmd":30,"feats":[{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Mobility"},{"feat":"Power Attack"}],"skills":[{"skill":"Craft (any one)","value":15},{"skill":"Diplomacy","value":16},{"skill":"Fly","value":23},{"skill":"Knowledge (planes)","value":15},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Spellcraft","value":15},{"skill":"Stealth","value":13}],"languages":["Celestial","Common","Ignan","telepathy 100 ft."],"environments":["any (Plane of Fire)"],"organizations":["solitary","pair","company (3-6)","band (7-12)"],"treasure":"standard (masterwork scimitar)","description_visual":"This creature resembles a ten foot tall human with brick-red skin and coal-black hair, long and braided.","group":"Genie","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Fire Burst","kind":"Su","details":"Once every 1d4 rounds as a standard action, a seraph can emit a blast of elemental fire in a 30-foot-radius burst. Creatures in the area take 8d6 points of fire damage. A successful DC 19 Reflex save reduces the damage by half. The save DC is Constitution-based."},{"type":"Heat","kind":"Ex","details":"A seraph generates so much heat that its mere touch deals an additional 1d6 points of fire damage. A seraph's metallic weapons also conduct this heat. A seraph can start or stop this ability as a free action once per round on its turn."}],"description":"The seraphs are genies from the Plane of Fire, and the sworn enemies of the efreet. A violent war between the two genie races has spanned centuries and spilled into an uncountable number of planes. Any encounter between a seraph and an efreeti sparks a battle that only ends when one or the other is killed. Those that aid the efreeti are treated by seraphs as if they were efreeti themselves; no mercy is shown in battle to an ally of the hated fire genies. The seraphs often align themselves with djinn as they both share the efreeti as a common enemy.\n\nA seraph prefers to use its spell-like abilities over melee weapons in combat, often allowing its opponents to move in close so the seraph can unleash its fire burst. A seraph facing overwhelming odds in battle attempts to flee; covering its escape by turning invisible or erecting a wall of fire between itself and its enemies. When battling efreet, a seraph often employs cold-based magic weapons such as frost scimitars and icy burst spears.\n\nA typical seraph stands 10 ft. tall and weighs about 1,500 pounds.\n\nSome seraphs are noble, known as beys or caliphs. A noble seraph has 14 Hit Dice and gains the following spell-like abilities: 3/day-fire seeds, heat metal; 1/day- elemental swarm (fire elementals only), greater invisibility. A noble seraph's caster level for its spell-like abilities is 16th. Noble seraphs are CR 10.","ecology":"","habitat_society":""},{"name":"Shadow Hunter","cr":8,"xp":4800,"alignment":"N","size":"Huge","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"tremorsense","modifier":"60 ft."}],"ac":18,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+2 Dex, +8 natural, -2 size","hp":76,"hd":"8d10+32","hdvalue":8,"fort":10,"ref":8,"will":4,"defensive_abilities":["shadowblend"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":20},{"type":"swim","speed":30}],"melee":"bite +14 (1d8+10 plus poison plus grab)","space":"15 ft.","reach":"10 ft.","strength":24,"dexterity":15,"constitution":19,"intelligence":5,"wisdom":14,"charisma":3,"baseatk":8,"cmb":17,"cmb_special":"+4 vs. grapple","cmd":29,"cmd_special":"can't be tripped","feats":[{"feat":"Ability Focus (poison)"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Perception","value":12},{"skill":"Stealth","value":4,"special":"+14 in dimly lit & unlit areas"},{"skill":"Swim","value":15}],"sq":[{"type":"hunt by scent"}],"environments":["any underground"],"organizations":["solitary","pair","trio","nest (1-3 adults and 5-8 hatchlings)"],"treasure":"standard","description_visual":"The shadow hunter is a great, dark serpent that dwells in deep caverns beneath the earth, where it hunts dark elves and other Medium to Large sized creatures. An adult specimen is over 40 ft. long and nearly 5 ft. thick in its midsection. In bright light it can be seen to be covered with non-reflective black scales, and its underbelly is the dark red of clotted blood. Shadow hunters have the supernatural ability to blend in with shadows, both to protect themselves and to stalk and ambush prey. Unlike normal snakes, shadow hunters often work in groups of two or three to corner prey in passages.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Shadowblend","kind":"Su","details":"In areas of dim and no light, shadow hunters gain improved concealment; there is a 40% miss chance when attacking one in such conditions."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save DC 20 Fort; frequency 1/ round for 6 rounds; effect 1d4 Constitution damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Hunt by Scent","kind":"Ex","details":"Shadow hunters are expert at tracking prey through the dim warrens where they dwell. They can track using their Perception skill in place of Survival."}],"description":"Shadow hunters generally prefer to hunt in networks of twisting passages that allow them to move around their intended prey, or even approach it from multiple directions. They are particularly fond of elf flesh, but eats any Small to Large creature as long as it is living, organic, and animal-based (i.e., not a plant or fungus). When they attack, they prefer to strike and envenom their prey, holding on and chewing the poison into their opponent until it stops struggling. If there is more than one foe present, they don't try to grab their prey, preferring to strike at those that threaten it, retreating if need be to return later to consume their hopefully dead prey.","ecology":"","habitat_society":""},{"name":"Shadow Wing","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"superior low-light vision"}],"ac":23,"ac_touch":14,"ac_flat_footed":18,"ac_mods":"+5 Dex, +9 natural, -1 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":11,"ref":12,"will":4,"speed":[{"type":"land","speed":20},{"type":"fly","speed":80,"maneuverability":"average"}],"melee":"bite +13 (2d6+4), 2 wings +8 (1d8+2 plus poison)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"shadow blend"}],"strength":19,"dexterity":21,"constitution":18,"intelligence":8,"wisdom":12,"charisma":11,"baseatk":10,"cmb":15,"cmd":30,"feats":[{"feat":"Alertness"},{"feat":"Greater Flyby Attack"},{"feat":"Flyby Attack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Fly","value":8},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":3},{"skill":"Stealth","value":11,"special":"+19 in darkness"}],"languages":["Auran","Common"],"environments":["temperate mountains"],"organizations":["solitary","flock (2-5)","roost (3-6)"],"treasure":"none","description_visual":"This giant creature seemingly composed of the night itself resembles a mix of hawk and manta ray.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Wing-injury; save DC 19 Fort; frequency 1/ round for 6 rounds; effect 1d6 Strength damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Shadow Blend","kind":"Su","details":"During any conditions other than bright light, a shadow wing can disappear into the shadows as a move-equivalent action, effectively becoming invisible. Artificial illumination or light spells of 2nd level or lower don't negate this ability."},{"type":"Superior Low-Light Vision","kind":"Ex","details":"A shadow wing can see five times as far as a human in dim light."}],"description":"Shadow wings are nocturnal predators formed of inky blackness that resemble a cross between a giant hawk and giant tailless manta ray. They are fierce hunters, and once prey is sighted, shadow wings are relentless in their pursuit. A typical shadow wing hunter claims a territory in a 5 mile radius around its lair. To the shadow wing, any living creature entering this area is fair game.\n\nThe common shadow wing makes its lair within a secluded and hard to reach cave high in mountainous regions. A typical nest contains 2 adults and 1d4 newborns or 2d4 eggs. Shadow wing eggs are blackish-blue in color and soft and leathery to the touch.\n\nShadow wings prefer to scout for food under the cover of darkness when their shadow blend ability is the most useful. Using its superior vision it almost always sights its target before they ever know the shadow wing is there. Prey is killed and either devoured on the spot or carried back to the lair.\n\nA shadow wing measures 9 ft. long and has a wingspan of 20 ft. Its body is composed of darkness and shadowstuff and it resembles a manta ray with a hawk's head. Its beak is formed of the same inky blackness as the rest of its form. Other than two piercing red eyes no other discernible features can be made out in its form. Shadow wings speak with a low, raspy voice.\n\nA shadow wing attacks by swooping low at an opponent and slashing it with its wings or stabbing with its beak. Since most attacks instigated by shadow wings occur under the cover of darkness, they use their shadow blend ability to conceal themselves from their foes.","ecology":"","habitat_society":""},{"name":"Silverfish Swarm","cr":8,"xp":4800,"alignment":"N","size":"Fine","type":"vermin","subtypes":["swarm"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":24,"ac_touch":21,"ac_flat_footed":21,"ac_mods":"+3 Dex, +3 natural, +8 size","hp":105,"hd":"14d8+42","hdvalue":14,"fort":12,"ref":7,"will":4,"defensive_abilities":["swarm traits","vermin traits"],"immunities":["mind-affecting effects","weapon damage"],"speed":[{"type":"land","speed":30}],"melee":"swarm (3d6 plus distraction and 3d6 acid)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 20"}],"strength":1,"dexterity":16,"constitution":16,"wisdom":10,"charisma":2,"baseatk":10,"environments":["temperate forests","any underground","any urban","warm forests"],"organizations":["solitary","pair","infestation (3-6)"],"treasure":"none","description_visual":"This mass of flattened, silver insects moves forward in a wriggling, fish-like motion.","source":"Tome of Horrors 4 (3pp)","description":"Silverfish swarms are highly destructive creatures, consuming anything and everything they encounter.","ecology":"","habitat_society":""},{"name":"Slaughterford","cr":8,"xp":4800,"alignment":"NE","size":"Medium","type":"monstrous humanoid","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":14,"ac_flat_footed":16,"ac_mods":"+4 Dex, +6 natural","hp":95,"hd":"10d10+30 (+10)","hdvalue":10,"fort":6,"ref":11,"will":8,"sr":19,"speed":[{"type":"land","speed":40}],"melee":"2 arm blades +13 (1d8+3/19-20 x3) or flurry  +11 (1d8+3/19-20 x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"augmented critical"},{"type":"flurry of blows"},{"type":"rend armor"}],"strength":16,"dexterity":18,"constitution":17,"intelligence":11,"wisdom":12,"charisma":13,"baseatk":10,"cmb":13,"cmd":27,"feats":[{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Critical"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Intimidate","value":14},{"skill":"Perception","value":14},{"skill":"Stealth","value":17}],"languages":["Aklo"],"sq":[{"type":"flurry of blows"},{"type":"rend armor"}],"environments":["any underground"],"organizations":["solitary","gang (2-5)"],"treasure":"standard","description_visual":"A wiry figure approaches, its hairless body inhumanly slender and frail looking. It has two sets of arms, a smaller pair of stunted normal looking arms and a longer primary set knotted with wiry muscle with malformed forearms ending in long cartilaginous blades.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Flurry of Blows","kind":"Ex","details":"Similar to a monk, a slaughterford can make a flurry of blows attack at the expense of accuracy. It can make one extra attack per round as a full attack action, but each attack receives a -2 penalty."},{"type":"Rend Armor","kind":"Ex","details":"If a slaughterford hits with both arm blades, it pulls apart any armor worn by its foe. This attack deals 2d8+6 points of damage to the opponent's armor. Creatures not wearing armor are unaffected by this special attack. Armor reduced to 0 hit points is destroyed. Damaged armor may be repaired with a successful Craft (armorsmithing) check."}],"description":"Sometimes known as reaperborn, slaughterfords were bred from unknown humanoid stock by long-forgotten wizards in ages past. They typically dwell underground in burrows or caves and only venture to the surface world at night. They are not harmed by sunlight, but don't like it.\n\nSlaughterfords move with an odd grace, capable of inhuman feats of agility and flexibility. Their faces are twisted mockeries of human expression, bearing reddish eyes, large noses, and perpetual sneers of evil and rage. Their secondary arms are much weaker and are only used for simple manipulation, never for combat. When the slaughterford is engaged in combat, it keeps its secondary arms folded against its belly.\n\nA slaughterford strikes with its arm blades. In melee it relentlessly slashes and stabs until either it or its opponent is dead. It can use both of its arm blades with equal proficiency. Heavily armored opponents are subjected to its armor rending ability before being slashed and stabbed. A slaughterford gang works in concert to slay their foes, though when faced with overwhelming odds, slaughterfords attempt to flee.","ecology":"","habitat_society":""},{"name":"Stone Maiden","cr":8,"xp":4800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":10,"ac_flat_footed":20,"ac_mods":"+10 natural","hp":95,"hd":"10d10+40","hdvalue":10,"fort":11,"ref":5,"will":12,"defensive_abilities":["one with the earth"],"dr":"10/magic","immunities":["earth magic","elemental traits"],"weaknesses":["veil"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":30}],"melee":"longsword +16 (1d8+5) or 2 slams +15 (1d8+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"earth mastery"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"magic stone"},{"spell":"meld into stone"},{"spell":"soften earth and stone"},{"spell":"spike stones"},{"spell":"stone shape"},{"spell":"stone tell"},{"spell":"transmute mud to rock"},{"spell":"transmute rock to mud"}]},{"frequency":"1/day","spells":[{"spell":"iron body"},{"spell":"wall of stone"}]},{"frequency":"3/day","spells":[{"spell":"move earth"}]}],"strength":20,"dexterity":10,"constitution":18,"intelligence":15,"wisdom":16,"charisma":20,"baseatk":10,"cmb":15,"cmd":25,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Craft (stonemasonry)","value":15},{"skill":"Diplomacy","value":18},{"skill":"Knowledge (dungeoneering)","value":15},{"skill":"Knowledge (planes)","value":15},{"skill":"Knowledge (nature)","value":15},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":16},{"skill":"Survival","value":16}],"languages":["Common","Sylvan","Terran"],"environments":["any (Elemental Plane of Earth)"],"organizations":["solitary","troupe (2-5)"],"treasure":"standard","description_visual":"This creature resembles an exquisitely carved statue, female and shapely in design. Loose-fitting robes clothe her form and a veil hangs across her shoulders and wraps around her head, though her face isn't obscured. Her skin is the color of shale.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Animate Rocks","kind":"Su","details":"A stone maiden can animate rocks within 180 ft. at will, controlling up to two rocks at a time. Animated rocks are vaguely humanoid-shaped (most often resembling a stone maiden) and use the same statistics as stone maidens. They don't possess a stone maiden's animate rocks ability, spell-like abilities, or veil special quality. They can move through a spike stoned area unimpeded and without taking damage. An animated rock loses its ability to move if the stone maiden that animated it is incapacitated or moves out of range."},{"type":"Earth Mastery","kind":"Ex","details":"A stone maiden gains a +1 bonus on attack and damage rolls if both it and its foe are touching the ground. If an opponent is airborne or waterborne, the stone maiden takes a -4 penalty on attack and damage rolls. (These modifiers are not included in the statistics block.)"},{"type":"Immunity to Earth Magic","kind":"Ex","details":"A stone maiden is immune to all spells, spell-like abilities, and supernatural effects with the earth descriptor, including spells of the Earth domain."},{"type":"One with the Earth","kind":"Ex","details":"A stone maiden is so closely tied with the earth that any damage it takes from the natural attacks of an earth or stone creature (one formed of earth or stone or one with the earth subtype) is considered nonlethal damage."},{"type":"Veil","kind":"Su","details":"Each stone maiden is mystically bound to her veil and never lets it out of her possession. If she is ever more than 1,000 ft. from it, she weakens (-4 effective penalty to Strength, Dexterity, and Constitution) and dies within 4d6 hours, crumbling to dust. If her veil is ever destroyed (hardness 3, hp 10) shed ies within 1 minute. A stone maiden's veil doesn't radiate magic."}],"description":"Stone maidens are reclusive creatures of elemental earth thought to be somehow related to dryads and other fey creatures of earth and nature. How sages came to this conclusion is unknown (but one can venture a guess and say it is because like many fey creatures, such as nymphs, dryads, and nereids, the stone maiden is a strikingly attractive female creature). They spend almost of their time on the Elemental Plane of Earth, rarely venturing into the Material Plane, unless summoned. If summoned by a spellcaster, a stone maiden performs the task asked of her (if she can and if it doesn't go against her alignment) and quickly returns to her home plane.\n\nStone maidens rarely associate with other races, preferring to deal only with those of their own kind (meaning earth creatures). They are often found in the company of geons, non-evil vilstraks, and earth elementals.\n\n(It is rumored the Elemental Lord of Earth has a personal harem of stone maidens in his private palace.) A stone maiden's features are delicate and smooth. Her hair (almost always hidden by her veil) is long and flowing, and generally darker than her grayish \"skin.\" A typical stone maiden stands about 6 ft. tall.\n\nA stone maiden can be summoned using a summon monster VII, planar ally (or greater), or planar binding (or greater) spell.\n\nA stone maiden is reluctant to enter combat unless pressed. Once engaged, a stone maiden defends itself with its longsword (or slam attack if unarmed) and an array of spell-like abilities.\n\nA stone maiden usually opens combat by animating a section of nearby rock and directing the animated rocks to attack her nearest opponents. Next, she uses spike stones to turn the ground between herself and her foes into a field of razor-sharp points (and remember, because of her immunity to earth magic, a stone maiden can move through a spike stoned area unimpeded and without taking damage). Creatures making their way through the spike stoned area are usually met with a wall of stone or a hail of magic stones.\n\nIf combat goes against a stone maiden she uses meld into stone to escape.","ecology":"","habitat_society":"","gear":"longsword"},{"name":"Trapper","cr":8,"xp":4800,"alignment":"N","size":"Huge","type":"aberration","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":19,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+1 Dex, +10 natural, -2 size","hp":117,"hd":"12d8+63","hdvalue":12,"fort":8,"ref":7,"will":11,"defensive_abilities":["amorphous"],"dr":"10/slashing or piercing","resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":10}],"melee":"buffet +17 (1d8+15)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"smother"}],"strength":30,"dexterity":12,"constitution":19,"intelligence":14,"wisdom":15,"charisma":14,"baseatk":9,"cmb":21,"cmb_special":"+4 vs. grapple","cmd":32,"cmd_special":"can't be tripped","feats":[{"feat":"Blind-Fight"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":25},{"skill":"Knowledge (dungeoneering)","value":17},{"skill":"Knowledge (engineering)","value":14},{"skill":"Perception","value":23},{"skill":"Stealth","value":14,"special":"+26 in areas of natural or worked stone"},{"skill":"Survival","value":17}],"languages":["Common","Undercommon (cannot speak)"],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard","description_visual":"This massive creature resembles a manta ray with brownish-gray flesh turning lighter on its underside. No discernible eyes or appendages can be seen.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Smother","kind":"Ex","details":"A trapper can try to wrap a creature up to one size smaller than itself in its body as a standard action. The trapper attempts a grapple that doesn't provoke an attack of opportunity. If it wins the grapple check, it establishes a hold and deals buffet damage each round the hold is maintained. Further, a grappled opponent must hold its breath or suffocate. Attacks that hit a smothering trapper deal half their damage to the monster and half to the trapped victim."}],"description":"Trappers are thought to be distant relatives of the lurker above (see that entry). Unlike their relatives, however, trappers mimic the floor of a building, dungeon, or other structure. By manipulating their body structure while covering the floor, trappers can form a box that resembles a small trunk or chest. This is usually enough to lure would-be-adventurers to their doom.\n\nA trapper waits until its prey is almost centered on its body near the \"trunk\" or \"chest\" before it strikes. It then quickly folds and wraps its body around its unsuspecting prey attempting to smother and squeeze it until it is dead.","ecology":"","habitat_society":"","credit":"The Trapper originally appeared in the Strategic Review #5 (© TSR/ Wizards of the Coast, 1975) and later in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission."},{"name":"Uggoth","cr":8,"xp":4800,"alignment":"CE","size":"Medium","type":"aberration","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect thoughts"}],"ac":22,"ac_touch":13,"ac_flat_footed":19,"ac_mods":"+2 Dex, +1 dodge, +9 natural","hp":67,"hd":"9d8+27","hdvalue":9,"fort":6,"ref":7,"will":12,"defensive_abilities":["spell reflection"],"dr":"10/cold iron","sr":19,"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"2 claws +10 (1d4+4), 4 tentacles +10 (1d6+4 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"mind thrust"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"charm person"},{"spell":"detect thoughts"},{"spell":"hypnotic pattern"},{"spell":"suggestion"}]},{"frequency":"1/day","spells":[{"spell":"charm monster"},{"spell":"mass suggestion"},{"spell":"plane shift"}]}],"strength":19,"dexterity":15,"constitution":17,"intelligence":19,"wisdom":19,"charisma":21,"baseatk":6,"cmb":10,"cmb_special":"+4 vs. grapple","cmd":23,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Bluff","value":14},{"skill":"Diplomacy","value":14},{"skill":"Intimidate","value":17},{"skill":"Knowledge (any one)","value":13},{"skill":"Knowledge (arcana)","value":16},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":13},{"skill":"Spellcraft","value":12},{"skill":"Swim","value":12},{"skill":"Use Magical Device","value":9}],"languages":["Aquan","Common","Draconic","Undercommon"],"sq":[{"type":"water breathing"}],"environments":["any underground"],"organizations":["solitary","gang (2-4)"],"treasure":"standard","description_visual":"This hideous humanoid creature has the lower torso of an octopus and the upper torso of a human. Two long tentacles protrude from each side of the creature's body, just beneath its arms. Its head, while vaguely human, is hairless and features an elongated skull.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Mind Thrust","kind":"Su","details":"Three times per day, a uggoth can unleash a blast of mental energy at a single target within 40 ft. The blast deals 8d6 points of damage to a single target if it fails a DC 24 Will save. This is a mind-affecting effect. The save DC is Charisma-based."},{"type":"Spell Reflection","kind":"Su","details":"Any spell that fails to overcome a uggoth's spell resistance is reflected back on the caster who becomes the target of the spell. Area spells still affect the area around the uggoth, but the portion that would affect it is reflected back on the caster."},{"type":"Tentacles","kind":"Ex","details":"A uggoth's tentacles are always primary attacks for the creature."}],"description":"Uggoths are subterranean creatures once bent on destruction and expanding their own realm from the underworld to the surface world. Legends say the uggoth race was formed when a band of ancient humans offended their gods and were forever cursed. Scholars cannot verify or disprove this origin myth.\n\nUggoths dwell in great underground cities, most of which are built and maintained by slave labor. Once an ambitious race with desires to rule both underground and aboveground, uggoths now spend most of their time lounging in their homes or in public places within the uggoth cities partaking of various dream-inducing narcotics. They are still very active in trade, usually trading with other evil-aligned subterranean races. In exchange for various foods, manufactured weapons, and spices, the uggoth receive slaves, exotic herbs, and the like.\n\nUggoths stand between 6 and 7 ft. tall and weigh 160 to 180 pounds. Their humanoid flesh is dark amber and leathery to the touch. Their lower torsos are even darker amber fading to black near the tips of the tentacles. Uggoths live for 150 years typically.\n\nA uggoth attack with its mind thrust attack in an effort to dispatch its enemies as quickly and efficiently as possible. Creatures that survive are attacked with various spell-like abilities and slashed or grabbed by the creature's tentacles. Opponents that are killed are usually devoured on the spot or carried back to the uggoth's dwelling and eaten later or fed to the young. Opponents that show promise as slaves are captured instead of killed. Potential slaves are carted back to the uggoth's city and placed in a public slave pen where they are eventually sold to the highest bidder. Occasionally the city's overseer allows the uggoth to keep captured slaves.","ecology":"","habitat_society":""},{"name":"Undead Fire Elemental","cr":8,"xp":4800,"alignment":"NE","size":"Medium","type":"undead","subtypes":["cold"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+4 Dex, +1 dodge, +5 natural","hp":102,"hd":"12d8+36 (+12)","hdvalue":12,"fort":7,"ref":8,"will":8,"defensive_abilities":["chill shield"],"immunities":["cold","fire","undead traits"],"speed":[{"type":"land","speed":50}],"melee":"slam +13 (1d6+4 plus 1d6 cold and coldfire)","space":"5 ft.","reach":"5 ft.","strength":16,"dexterity":19,"intelligence":4,"wisdom":11,"charisma":16,"baseatk":9,"cmb":12,"cmd":27,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":15}],"languages":["Ignan"],"sq":[{"type":"snuff"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"A pillar of black flame glowing with a bluish nimbus seems to contain a humanoid shape at its heart. The crackling flames give off an intense chill that drains the heat from the surrounding air.","group":"Undead Elemental","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Chill Shield","kind":"Su","details":"In addition to being immune to cold and fire, the flames that wreath an undead fire elemental also act as a fire shield spell. Any creature striking the undead fire elemental with a natural or handheld weapon takes 1d6+12 points of cold damage. This effect cannot be dispelled."},{"type":"Coldfire","kind":"Su","details":"Each time an undead fire elemental successfully hits a living creature, that creature must make a DC 19 Fortitude save or catch on fire from the elemental's cold flames. These flames deal 1d6 Strength damage per round as the life-giving heat is snuffed from its body. The afflicted creature is entitled to a new saving throw each round. This coldfire burns for 1d6 rounds or until a successful save is made. Resistance to cold or fire doesn't prevent this damage, though death ward does. The save is Charisma based."},{"type":"Snuff","kind":"Ex","details":"As a standard action (that doesn't provoke an attack of opportunity), an undead fire elemental can extinguish itself, thereby reducing itself to the form of its base component - a small pile of cold ashes. The undead fire elemental will rarely do this while in the presence of other creatures because of the inherent vulnerability involved. If the cold ash can be scooped up and placed in a stoppered container, the undead fire elemental is trapped until released. Likewise if the ash pile is exposed to winds of 50 mph or greater, the undead fire elemental's material form is dispersed, and it is unable to manifest its burning form again until it is able to reform its ash pile - a process usually taking several years. While in its ash pile form, an undead fire elemental can burst into its burning form as a free action without provoking an attack of opportunity."}],"description":"Occasionally a horrible tragedy befalls a summoned fire elemental such that it is destroyed but isn't permitted to return to its plane of origin. When this happens, what can eventually form is a horrendous creature composed of its original element infused with raw negative energy. The resulting undead creature is an abomination to its element, seeking nothing more than to snuff out all heat it encounters. Divorced of its natural element, undead fire elementals are no longer hindered by water or bodies of nonflammable liquids.\n\nAn undead fire elemental stands 7 ft. tall but weighs only 75 pounds due to its ephemeral nature.\n\nUndead fire elementals retain the ability to speak Ignan but rarely deign to speak to those they are about to consume in their cold fury.\n\nUndead fire elementals usually remain in their lairs, morosely remembering their prior warm existence. However, when anything living comes within range, they quickly resume their burning form and surprise attack with glee to forever destroy the heat that they sense in their prey.","ecology":"","habitat_society":"","credit":"Original author Greg A. Vaughan  Originally appearing in Slumbering Tsar (© Frog God Games/ Greg A. Vaughan, 2012)"},{"name":"Vampiric Ooze","cr":8,"xp":4800,"alignment":"CE","size":"Large","type":"undead","init":-1,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":4,"ac_touch":4,"ac_flat_footed":4,"ac_mods":"-5 Dex, -1 size, +0 natural","hp":52,"hd":"12d8-12 (+12)","hdvalue":12,"fort":2,"ref":-2,"will":1,"defensive_abilities":["split (cold and electricity, 10 hp)"],"immunities":["cold","electricity","ooze traits","undead traits"],"weaknesses":["sunlight vulnerability"],"speed":[{"type":"land","speed":10},{"type":"climb","speed":10}],"melee":"slam +10 (2d4+3 plus energy drain and grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"2d4+3"},{"type":"create spawn"},{"type":"energy drain","details":"1 level, DC 14"}],"strength":15,"dexterity":1,"wisdom":1,"charisma":8,"baseatk":9,"cmb":12,"cmb_special":"+4 vs. grapple","cmd":17,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Inititiative","type":"bonus"},{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":3}],"environments":["any underground"],"organizations":["solitary","pack (vampiric ooze plus 2-4 zombies)"],"treasure":"none","description_visual":"This creature looks like a thick, bubbling pool of mustard yellow muck or goo.","group":"Ooze","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Create Spawn","kind":"Su","details":"Any humanoid slain by a vampiric ooze becomes a zombie in 1d4 rounds. Spawn are under the command of the vampiric ooze that created them and remain enslaved until its death. They don't possess any of the abilities they had in life."},{"type":"Sunlight Vulnerability","kind":"Ex","details":"Exposing a vampiric ooze to direct sunlight staggers it on the first round, and it is destroyed utterly in the next round if it cannot escape."}],"description":"The vampiric ooze is thought to have been created by a great undead spellcaster using ancient and forbidden magic. Some believe the vampiric ooze was formed when an ochre jelly slew a vampire and absorbed it. It can alter its shape so as to appear up to 12 ft. long and 6 inches thick; it can also compress its body to slip through cracks as small as 1 inch wide.\n\nIt spends its time slithering along floors, walls, and ceilings, or if above ground, hunting its prey at night.\n\nA vampiric ooze attempts to envelop and constrict its prey, dealing negative levels with its slam attack.","ecology":"","habitat_society":""},{"name":"Vile Drake","cr":8,"xp":4800,"alignment":"CE","size":"Large","type":"dragon","subtypes":["water"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":20,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+2 Dex, +9 natural, -1 size","hp":94,"hd":"9d12+36","hdvalue":9,"fort":10,"ref":10,"will":6,"immunities":["paralysis","sleep"],"resists":[{"type":"acid","value":20}],"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"average"},{"type":"swim","speed":20}],"melee":"bite +13 (2d6+5/19-20 plus disease), 2 claws +13 (1d6+5)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"acid breath"},{"type":"disease"},{"type":"savage bite"}],"strength":21,"dexterity":14,"constitution":18,"intelligence":8,"wisdom":10,"charisma":12,"baseatk":9,"cmb":15,"cmd":27,"feats":[{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":12},{"skill":"Intimidate","value":13},{"skill":"Perception","value":15},{"skill":"Stealth","value":10},{"skill":"Survival","value":7},{"skill":"Swim","value":21}],"languages":["Draconic"],"sq":[{"type":"speed surge"},{"type":"swamp stride"},{"type":"water breathing"}],"environments":["temperate marshes","warm marshes"],"organizations":["solitary","pair","wing (3-8)"],"treasure":"standard","description_visual":"This sleek dragon is black in color with graceful wings and a horned head. Sizzling acid drips from its toothy maw.","group":"Drake","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Acid Breath","kind":"Su","details":"A vile drake can, as a standard action, spit a ball of liquid that explodes into a cloud of acid. This attack has a range of 60 ft. and deals 6d6 points of acid damage (DC 17 Reflex half) to all creatures in a 20-foot radius spread. Additionally, a creature that fails its save takes 3d6 points of acid damage one round after failing its save. Once a vile drake has used its acid breath, it cannot do so again for 1d6 rounds. The save DC is Constitution-based."},{"type":"Disease","kind":"Su","details":"Marsh Sickness: Bite-injury; save DC 17 Fort; onset 1 day; frequency 1/day; effect 1d3 Con and 1d3 Int damage. A creature whose Int score drops below 12 as a result of marsh sickness acts as if affected by a confusion spell (CL 9th) until the disease is cured; cure 2 saves. The save DC is Constitution-based."},{"type":"Savage Bite","kind":"Ex","details":"A vile drake applies 1-1/2 times its Strength bonus to damage dealt with its bite attack, and it threatens a critical hit on a 19-20."},{"type":"Speed Surge","kind":"Ex","details":"Three times per day as a swift action, a vile drake may draw on its draconic heritage for a boost of strength and speed to take an additional move action in that round."},{"type":"Swamp Stride","kind":"Ex","details":"A vile drake can move through bogs and quicksand without penalty at its normal speed."},{"type":"Water Breathing","kind":"Ex","details":"A vile drake can breathe underwater indefinitely and can freely use its acid breath and other abilities while submerged."}],"description":"Vile drakes prey upon those creatures unlucky enough to find themselves caught in the drake's territory. Travelers, fishermen, crocodiles, lizardfolk, and chikes (see their entry in this book) are the usual victims and subsequent meals of vile drakes. Prey that isn't devoured immediately is carried back to their swampy lairs and stored under the muck and mud for later consumption.\n\nVile drakes are about 9 ft. long and weigh close to 800 pounds. Their scales are usually black or dark gray, with lighter colors present on their undersides. Eyes are always dark in color. Vile drakes mate for life with the female laying a clutch of up to five eggs once per year. Eggs are laid in the mud and buried to hide them from predators and poachers. Eggs hatch within 9 months. Young reach maturity rapidly, usually within 3 years. Vile drakes, on average, live up to 200 years.\n\nVile drakes often stalk their prey for miles before attacking. They are generally pack hunters and so encounters with a solitary vile drake are rare. When they spring to attack, vile drakes open with their breath weapon, and then rush in to bite with their nasty fangs.","ecology":"","habitat_society":""},{"name":"Wolf-in-sheep's-clothing","cr":8,"xp":4800,"alignment":"N","size":"Medium","type":"aberration","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":10,"ac_flat_footed":18,"ac_mods":"+8 natural","hp":93,"hd":"11d8+44","hdvalue":11,"fort":7,"ref":5,"will":9,"defensive_abilities":["all-around vision"],"immunities":["flanks"],"speed":[{"type":"land","speed":5}],"melee":"bite +11 (1d6+3), 7 tentacles +10 (1d4+1 plus grab)","space":"5 ft.","reach":"5 ft. (10 ft. with tentacle)","special_attacks":[{"type":"constrict","details":"1d4+3"}],"strength":17,"dexterity":10,"constitution":19,"intelligence":6,"wisdom":14,"charisma":8,"baseatk":8,"cmb":11,"cmb_special":"+4 vs. grapple","cmd":21,"feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Improved Lightning Reflexes"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Perception","value":20,"special":"+24 vision-based checks"},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":14,"special":"+22 in forested surroundings"}],"sq":[{"type":"lure-growth"}],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"none","description_visual":"Before you stands a grayish-brown tree stump about 3-4 ft. in diameter. Sitting atop the tree stump is a small white-furred rabbit.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"All-Around Vision","kind":"Ex","details":"The wolf-in-sheep's-clothing's 10- foot long eyestalks allow it to look in any direction, thereby granting it a +4 racial bonus on vision-based Perception skill checks. A wolf-in-sheep's-clothing cannot be flanked."},{"type":"Lure-Growth","kind":"Ex","details":"A wolf-in-sheep's-clothing can sprout a small furry animal from its stump as a free action. It uses this ability to lure potential prey into range where it then attacks with its tentacles. A creature viewing the lure-growth must succeed on a DC 19 Wisdom check to detect the deception. The check DC is Constitution-based."}],"description":"The wolf-in-sheep's-clothing is perhaps the single strangest monster sages have cataloged to date. It appears as a gray-brown tree stump about 3-4 ft. in diameter. Two 10-foot long eyestalks protrude from the creature's base. Each eyestalk is brownish-green in color and is topped by a violet flower-like eye. Seven to ten root tentacles, black-brown in color, give the monster its means of locomotion. Its mouth is located on its trunk-like body and appears to be nothing more than a deep scar, except when the creature opens it. The mouth is lined with razor-sharp and jagged greenish-white teeth. Its strangest and perhaps deadliest characteristic is its ability to \"sprout\" a growth on its top that resembles a small furry animal (such as a rabbit or squirrel). The wolf-in-sheep's-clothing uses this ability to lure in its prey, when it strikes with deadly force and aim.\n\nThe wolf-in-sheep's-clothing uses its lure-growth ability to draw in prey.\n\nWhen a creature moves within 10 ft. of the wolf-in-sheep's-clothing, it lashes out with a tentacle. If it hits, it drags the prey to its mouth and bites until the creature dies.","ecology":"","habitat_society":"","credit":"The Wolf-In-Sheep's-Clothing originally appeared in the First Edition module S3 Expedition to the Barrier Peaks (© TSR/Wizards of the Coast, 1980) and later in the First Edition Monster Manual II (© TSR/ Wizards of the Coast, 1983) and is used by permission."},{"name":"Adult Dungeon Dragon","cr":9,"xp":6400,"alignment":"N","size":"Large","type":"dragon","subtypes":["shapechanger"],"init":0,"senses":[{"type":"dragon senses"}],"auras":["frightful presence (180 ft., DC 17)"],"ac":25,"ac_touch":9,"ac_flat_footed":25,"ac_mods":"+16 natural, -1 size","hp":104,"hd":"11d12+33","hdvalue":11,"fort":10,"ref":7,"will":12,"dr":"5/magic","immunities":["enchantment spells and effects","paralysis","sleep"],"sr":20,"speed":[{"type":"land","speed":30},{"type":"fly","speed":200,"maneuverability":"poor"}],"melee":"bite +17 (2d6+10), 2 claws +17 (1d8+7), 2 wings +15 (1d6+3), tail slap +15 (1d6+10)","space":"10 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"80 ft. line or 40 ft. cone, DC 18, confusion 1d6 rounds"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charm person"},{"spell":"detect thoughts"},{"spell":"suggestion"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":5,"spellsknown_concentration":8,"spellsknown":[{"spell_level":2,"spell_slots":5,"spells":[{"spell":"arcane lock"},{"spell":"magic mouth"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"hold portal"},{"spell":"shield"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mending"},{"spell":"read magic"}]}],"strength":25,"dexterity":11,"constitution":16,"intelligence":16,"wisdom":16,"charisma":14,"baseatk":11,"cmb":19,"cmd":29,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Craft Wondrous Item","type":"bonus"},{"feat":"Flyby Attack"},{"feat":"Iron Will"},{"feat":"Master Craftsman","type":"bonus"},{"feat":"Multiattack"},{"feat":"Skill Focus (Craft [crystal carving])"},{"feat":"Skill Focus (Knowledge [engineering])"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Craft (crystal carving)","value":15},{"skill":"Craft (traps)","value":11},{"skill":"Diplomacy","value":11},{"skill":"Disable Device","value":8},{"skill":"Fly","value":2},{"skill":"Knowledge (arcana)","value":17},{"skill":"Knowledge (dungeoneering)","value":10},{"skill":"Knowledge (engineering)","value":23},{"skill":"Linguistics","value":8},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":21},{"skill":"Spellcraft","value":17}],"languages":["Aklo","Common","Draconic","Gnoll","Goblin","Orc","Undercommon"],"sq":[{"type":"change shape","details":"alter self"},{"type":"craft crystal ball"}],"environments":["any underground"],"organizations":["solitary"],"treasure":"triple standard plus crystal ball","description_visual":"This dragon has a long serpentine neck, small wings, and glistening scales. Two small horns dominate its triangular head. Its body is gray in color, with scales tipped in flecks of gold and green. Its eyes are rounded and gray.","group":"Dragon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A dungeon dragon's breath weapon is a line or cone of warm mist. Creatures caught in the area must succeed on Fortitude save or be affected as if by a confusion spell for 1d6 rounds."},{"type":"Change Shape","kind":"Su","details":"At will, a very young or older dungeon dragon can assume the form of any Small or Medium humanoid creature (as the alter self spell). It can remain in its humanoid form indefinitely. It cannot take the form of a specific individual."},{"type":"Craft Crystal Ball","kind":"Ex","details":"Dungeon dragon parents begin teaching their wyrmlings the necessary skills and spells to craft a crystal ball soon after they leave the egg. A dungeon dragon gains the Master Craftsman feat for free as a bonus feat without having to meet the prerequisites."},{"type":"Craft Wondrous Item","kind":"Ex","details":"Older dungeon dragons create new crystal balls with additional powers as they grow in intelligence and spellcasting ability. A young adult dungeon dragon gains the Craft Wondrous Item feat for free as a bonus feat."},{"type":"Dominate Monster","kind":"Sp","details":"A great wyrm dungeon dragon can use this ability three times per day. It works as a dominate monster spell. This ability is the equivalent of an 8th-level spell. Skills Dungeon dragons gain a +4 bonus to Perception checks. Spell-like Abilities A dungeon dragon gains the following spell-like abilities, usable at will upon reaching the listed age category. Young-charm person; Juvenile-detect thoughts; Adult-suggestion; Old-charm monster; Ancient-mass suggestion; Great Wyrm-mass charm monster. The dungeon dragon uses these abilities to populate its dungeon with monsters it encounters in the surrounding terrain."}],"description":"The dungeon dragon is a curious creature that gets amusement by watching other beings engaged in life and death struggles. To this end, a dungeon dragon sets up a labyrinthine lair, setting traps and populating it with monsters. Younger dungeon dragons tend to lair in natural caverns to ease the burden of construction. Older, more experienced dungeon dragons have been known to construct their own sprawling subterranean complexes, even to the point of hiring on dwarf work gangs and swearing them to secrecy. Once the construction and refurbishing of its lair is complete, the dungeon dragon transforms itself into a humanoid and ventures into the surrounding countryside. There it spreads rumors and tales of this horrible catacomb in hopes of luring adventurers forth so it may watch them via its crystal ball. Young dungeon dragons often spend years living among humanoids, even to the point of joining adventurers involved in dungeon delves. On such adventures, the intrepid dungeon dragon takes notes regarding the devious traps and monsters it encounters so that it can add such things to its own lair. Oddly enough, although a dungeon dragon goes to great pains to amass a treasure hoard, it cares little for material wealth. Rather, it uses the treasure it gathers as bait in its dungeon to lure in adventurers and provide it the entertainment it so greatly desires. Watching adventurers explore its catacomb is the only real treasure a dungeon dragon desires. The only material possession a dungeon dragon will risk its life to save is its crystal ball. Without this vital piece of equipment, all of the dragon's labor is in vain. A dungeon dragon in its natural form prefers to flee any combat. It likes to watch other creatures engaged in fights for life, not itself. If forced into melee, it swats at opponents with its powerful claws and bite. A dungeon dragon is proficient in the use of all simple and martial weapons and light and medium armor and shields.","ecology":"","habitat_society":""},{"name":"Aurumvorax","cr":9,"xp":6400,"alignment":"N","size":"Small","type":"magical beast","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":23,"ac_touch":15,"ac_flat_footed":19,"ac_mods":"+4 Dex, +8 natural, +1 size","hp":114,"hd":"12d10+48","hdvalue":12,"fort":14,"ref":12,"will":7,"defensive_abilities":["ferocity"],"dr":"10/piercing or slashing","immunities":["poison"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":10}],"melee":"bite +18 (1d6+5 plus grab), 4 claws +18 (1d4+5 plus  grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rake","details":"4 claws +18, 1d4+5"}],"strength":21,"dexterity":18,"constitution":18,"intelligence":2,"wisdom":13,"charisma":11,"baseatk":12,"cmb":16,"cmb_special":"+8 vs. grapple","cmd":30,"cmd_special":"+12 vs. trip","feats":[{"feat":"Bleeding Critical"},{"feat":"Critical Focus"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":13},{"skill":"Stealth","value":17}],"environments":["any forests","any hills","temperate plains"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"This small, feral creature resembles an 8-legged wolf with bright golden fur.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Grab","kind":"Ex","details":"An aurumvorax can grab a foe of up to one size category larger than itself. It gains a +8 racial bonus to grapple attempts due to its multiple claws."}],"description":"The aurumvorax (also called the golden gorger) is an extremely vicious creature, attacking any living prey within its territory (and its territory often extends up to 1 mile in all directions away from its lair).\n\nThe aurumvorax is 3 ft. long and weighs about 200 pounds. The creature's claws end in razor-sharp, copper colored nails. The aurumvorax's eyes are silver with gold pupils. Small whiskers and hairs near its face are bronze in color.\n\nThe aurumvorax attacks by biting a foe and holding on with its powerful jaws. It then rips the foe apart with its claws. An aurumvorax that grabs its prey with its jaws doesn't release the hold unless broken until either it or its prey is dead.","ecology":"","habitat_society":"","credit":"The Aurumvorax originally appeared in the First Edition Monster manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Banyant","cr":9,"xp":6400,"alignment":"CG","size":"Huge","type":"plant","init":-1,"senses":[{"type":"low-light vision"}],"ac":19,"ac_touch":7,"ac_flat_footed":19,"ac_mods":"-1 Dex, +12 natural, -2 size","hp":114,"hd":"12d8+60","hdvalue":12,"fort":15,"ref":3,"will":8,"dr":"10/slashing","immunities":["plant traits"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":20}],"melee":"4 slams +14 (1d8+7/19-20)","ranged":"rock +7 (2d6+10)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"rock throwing","details":"150 ft."}],"strength":25,"dexterity":8,"constitution":21,"intelligence":12,"wisdom":14,"charisma":12,"baseatk":9,"cmb":18,"cmd":27,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (slam)"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Diplomacy","value":7},{"skill":"Intimidate","value":7},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":-2,"special":"+14 in native environs"},{"skill":"Survival","value":6}],"languages":["Banyant","Common","Sylvan"],"sq":[{"type":"animate plants"},{"type":"double damage against objects"},{"type":"plantspeech"}],"environments":["warm plains"],"organizations":["solitary","grove (2-7)"],"treasure":"standard","description_visual":"This animated tree has many large branches that writhe and thrash about it.","group":"Plant Guardian","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Animate Plants","kind":"Sp","details":"A plant guardian can animate any plants of the same type within 180 ft. at will, controlling up to two such plants at a time. It takes 1 full round for the plant to uproot itself, after which it moves at a speed of 10 ft. and fights as a plant of the same type as the one animating it (exceptions are noted in each entry below), gaining the plant guardian's vulnerability to fire. If the plant guardian that animated it terminates the animation, moves out of range, or is incapacitated, the plant immediately takes root wherever it is and returns to its normal state."},{"type":"Double Damage against Objects","kind":"Ex","details":"A plant guardian or animated tree that makes a full attack against an object or structure deals double damage."},{"type":"Plantspeech","kind":"Ex","details":"A plant guardian has the ability to converse with plants as if subject to a continual speak with plants spell, and most plants greet them with an attitude of friendly or helpful."}],"description":"The banyants are the plant guardians of warm plains such as savannas and equatorial grasslands. A banyant resembles a banyan tree.","ecology":"","habitat_society":""}];
